import { Checkbox as BaseCheckbox } from '@base-ui/react/checkbox';
import { CheckboxGroup as BaseCheckboxGroup } from '@base-ui/react/checkbox-group';
import { Check, Minus } from 'lucide-react';
import { useId, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { checkboxVariants, type CheckboxVariantProps } from './checkbox.variants';

const s = checkboxVariants();

export interface CheckboxProps extends Omit<BaseCheckbox.Root.Props, 'className'> {
  className?: string;
  ref?: Ref<HTMLElement>;
  /** Visible label. Without it, pass `aria-label` or wrap in a Field. */
  label?: ReactNode;
  /** Helper line under the label, linked with aria-describedby. */
  description?: ReactNode;
}

/**
 * Two-state (or indeterminate) checkbox. Controlled with `checked` + `onCheckedChange`,
 * uncontrolled with `defaultChecked`. Inside a CheckboxGroup, identify it with `value`.
 */
export function Checkbox({ label, description, className, ...props }: CheckboxProps) {
  const descId = useId();
  const control = (
    <BaseCheckbox.Root
      className={cn(s.root(), label != null && 'mt-px', label == null && className)}
      aria-describedby={description != null ? descId : undefined}
      {...props}
    >
      <BaseCheckbox.Indicator
        className={s.indicator()}
        render={(indicatorProps, state) => (
          <span {...indicatorProps}>
            {state.indeterminate ? <Minus size={13} strokeWidth={2.6} aria-hidden /> : <Check size={13} strokeWidth={2.6} aria-hidden />}
          </span>
        )}
      />
    </BaseCheckbox.Root>
  );
  if (label == null) return control;
  return (
    <div className={cn(s.item(), className)}>
      <label className={s.label()}>
        {control}
        <span className={s.labelText()}>{label}</span>
      </label>
      {description != null && (
        <p id={descId} className={s.description()}>
          {description}
        </p>
      )}
    </div>
  );
}

export interface CheckboxGroupProps extends Omit<BaseCheckboxGroup.Props, 'className'>, CheckboxVariantProps {
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

/**
 * Shared state for several checkboxes (`value` is the array of ticked `value`s). Name it with
 * `aria-labelledby`, or render it as a Fieldset: `<Fieldset render={<CheckboxGroup />}>`.
 * A `parent` checkbox plus `allValues` gives a "select all" with the indeterminate state.
 */
export function CheckboxGroup({ variant, className, ...props }: CheckboxGroupProps) {
  return <BaseCheckboxGroup className={cn(checkboxVariants({ variant }).group(), className)} {...props} />;
}

import { tv, type VariantProps } from '../../utils/tv';

export const checkboxVariants = tv({
  slots: {
    root: [
      'inline-flex size-[18px] shrink-0 cursor-pointer items-center justify-center rounded-[5px] border border-border bg-background text-primary-foreground',
      'transition-colors motion-reduce:transition-none hover:border-muted-foreground/50',
      'data-checked:border-primary data-checked:bg-primary data-indeterminate:border-primary data-indeterminate:bg-primary',
      'data-invalid:border-destructive/70',
      'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
      'data-disabled:cursor-not-allowed data-disabled:opacity-50',
    ],
    indicator: 'flex items-center justify-center data-unchecked:hidden',
    item: 'grid grid-cols-[auto_1fr] items-start gap-x-3 gap-y-0.5',
    label: 'col-span-2 grid cursor-pointer grid-cols-subgrid items-start has-[[data-disabled]]:cursor-not-allowed has-[[data-disabled]]:opacity-70',
    labelText: 'text-[13px] leading-5 font-medium text-foreground select-none',
    description: 'col-start-2 text-[12.5px] leading-5 text-muted-foreground text-pretty',
    group: 'flex flex-col',
  },
  variants: {
    variant: {
      plain: { group: 'gap-2.5' },
      list: { group: 'divide-y divide-border/60 overflow-hidden rounded-md border border-border bg-background/40 *:px-4 *:py-3.5' },
    },
  },
  defaultVariants: { variant: 'plain' },
});

export type CheckboxVariantProps = VariantProps<typeof checkboxVariants>;

export { Checkbox, CheckboxGroup, type CheckboxProps, type CheckboxGroupProps } from './Checkbox';
export { checkboxVariants, type CheckboxVariantProps } from './checkbox.variants';
export { doc as checkboxDoc } from './Checkbox.doc';

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Checkbox',
  group: 'Forms',
  status: 'stable',
  description: 'Checkbox with optional label and description, including the indeterminate state. CheckboxGroup shares state across several checkboxes (plain or bordered list layout) and supports a parent "select all" checkbox.',
  primitive: '@base-ui/react/checkbox, @base-ui/react/checkbox-group',
  pattern: 'checkbox (dual and mixed state)',
  keyboard: [
    ['Space', 'Toggles the focused checkbox; a parent checkbox ticks or clears the whole group'],
    ['Tab', 'Moves focus to the next checkbox (each checkbox is a tab stop)'],
  ],
  tokens: ['background', 'border', 'primary', 'primary-foreground', 'foreground', 'muted-foreground', 'destructive', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
